data.pageSchema:
{
  "renderer": "page",
  "body": [
    {
      "renderer": "form",
      "controls": [
        {
          "renderer": "input",
          "name": "projectTitle",
          "requiredOn": "1==1",
          "placeholder": "项目名",
          "type": "text",
          "minlength": 8,
          "maxlength": 20,
          "rules": []
        },
        {
          "renderer": "datepicker",
          "name": "createdAt",
          "readonly": false,
          "placeholder": "创建时间",
          "rules": []
        },
        {
          "renderer": "datepicker",
          "name": "updatedAt",
          "readonly": false,
          "placeholder": "更新时间",
          "rules": []
        },
        {
          "renderer": "action",
          "text": "搜索",
          "actionType": "submit",
          "body": {}
        }
      ],
      "submitType": "target",
      "inline": true,
      "target": "ProjectsTable"
    },
    {
      "renderer": "table",
      "name": "ProjectsTable",
      "updateOnRowId": "projectId",
      "columns": [
        {
          "label": "ID",
          "name": "projectId",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none"
        },
        {
          "label": "项目名",
          "name": "projectTitle",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none"
        },
        {
          "label": "项目描述",
          "name": "projectDesc",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none"
        },
        {
          "label": "项目图标",
          "name": "projectIcon",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none"
        },
        {
          "label": "立项人",
          "name": "createdBy",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none"
        },
        {
          "label": "创建时间",
          "name": "createdAt",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none"
        },
        {
          "label": "更新时间",
          "name": "updatedAt",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none"
        },
        {
          "label": "操作",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none",
          "body": [
            {
              "renderer": "action",
              "text": "团队成员",
              "actionType": "drawer",
              "body": {
                "body": [
                  {
                    "renderer": "cards",
                    "virtual": true,
                    "initApi": {
                      "url": "/api/users?withProject=true",
                      "method": "get",
                      "params": {
                        "name": "${username}"
                      }
                    },
                    "body": [
                      {
                        "renderer": "avatar",
                        "title": "<%=data.username%>",
                        "description": "<%=data.updatedAt%>",
                        "src": "${avatar}",
                        "size": 60,
                        "shape": "circle",
                        "borderRadius": 0,
                        "color": "#606266",
                        "bgColor": "#ffffff",
                        "body": [],
                        "classname": "move_3",
                        "isComputedSrc": true
                      },
                      {
                        "renderer": "action",
                        "text": "移除",
                        "isText": true,
                        "popupType": "confirm",
                        "visibleOn": "data.projectIds&&data.projectIds.includes(data.projectId)",
                        "size": "small",
                        "actionType": "ajax",
                        "actionApi": {
                          "url": "/api/user/${id}/project/${projectId}?status=0",
                          "method": "post",
                          "params": {}
                        },
                        "body": {},
                        "popoverTitle": "确定修改吗？",
                        "reload": "ProjectList",
                        "disabledOn": "data.createdBy === data.username"
                      },
                      {
                        "renderer": "action",
                        "text": "添加",
                        "isText": true,
                        "type": "success",
                        "popupType": "confirm",
                        "visibleOn": "data.projectIds&&!data.projectIds.includes(data.projectId)",
                        "size": "small",
                        "actionType": "ajax",
                        "actionApi": {
                          "url": "/api/user/${id}/project/${projectId}?status=1",
                          "method": "post",
                          "params": {}
                        },
                        "body": {},
                        "popoverTitle": "确定修改吗？",
                        "reload": "ProjectList"
                      }
                    ],
                    "shadow": "hover",
                    "span": 24,
                    "bodyClass": "project-list__each",
                    "name": "ProjectList",
                    "itemHeight": 80,
                    "updateOnRowId": "id"
                  }
                ],
                "footer": [
                  {
                    "renderer": "form",
                    "controls": [
                      {
                        "renderer": "input",
                        "name": "username",
                        "placeholder": "用户名",
                        "type": "text",
                        "rules": []
                      },
                      {
                        "renderer": "action",
                        "text": "搜索",
                        "actionType": "submit",
                        "body": {}
                      }
                    ],
                    "submitType": "target",
                    "inline": true,
                    "target": "ProjectList",
                    "classname": "project-list__search"
                  }
                ],
                "renderer": "drawer",
                "width": 25,
                "closeOnClickModal": true,
                "title": "添加团队成员"
              },
              "size": "small",
              "plain": true
            }
          ]
        }
      ],
      "actions": [
        {
          "renderer": "action",
          "text": "新增项目",
          "plain": true,
          "size": "small",
          "actionType": "dialog",
          "body": {
            "body": [
              {
                "renderer": "form",
                "controls": [
                  {
                    "renderer": "input",
                    "name": "projectName",
                    "label": "项目路径",
                    "requiredOn": "1==1",
                    "placeholder": "例：management",
                    "type": "text",
                    "minlength": 6,
                    "maxlength": 20,
                    "rules": [
                      {
                        "type": "api",
                        "trigger": "blur",
                        "exp": "/api/project/${projectName}/valid"
                      }
                    ]
                  },
                  {
                    "renderer": "input",
                    "name": "projectTitle",
                    "label": "项目名",
                    "requiredOn": "1==1",
                    "placeholder": "例：用户管理",
                    "type": "text",
                    "minlength": 8,
                    "maxlength": 20,
                    "rules": []
                  },
                  {
                    "renderer": "input",
                    "name": "projectDesc",
                    "label": "项目说明",
                    "requiredOn": "1==1",
                    "placeholder": "请输入",
                    "type": "text",
                    "minlength": 8,
                    "maxlength": 20,
                    "showWordLimit": true,
                    "rules": []
                  },
                  {
                    "renderer": "input",
                    "name": "projectIcon",
                    "label": "项目图标",
                    "placeholder": "请输入",
                    "type": "text",
                    "rules": [],
                    "requiredOn": "1==1"
                  }
                ],
                "name": "CreateForm",
                "actionApi": {
                  "url": "/api/project",
                  "method": "post",
                  "params": {
                    "*": "*"
                  }
                },
                "reload": "ProjectsTable"
              }
            ],
            "footer": [
              {
                "renderer": "action",
                "text": "创建",
                "actionType": "trigger",
                "triggered": "CreateForm",
                "body": {}
              }
            ],
            "renderer": "dialog"
          },
          "icon": "Plus"
        }
      ],
      "initApi": {
        "url": "/api/projects",
        "method": "get",
        "cached": false,
        "params": {
          "*": "*"
        }
      }
    }
  ],
  "innerStyle": ".project-list__each {\n  border-bottom: 1px solid #EBEEF5;\n  .i-avatar__container {\n    padding-top: 10px;\n  }\n  .i-action {\n    position: absolute;\n    right: 20px;\n    top: 50%;\n    transform: translateY(-50%)\n  }\n}\n.project-list__search {\n  .el-input {\n    width: 220px;\n  }\n}"
}
